//package round462;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;

public class C4 {
	InputStream is;
	PrintWriter out;
	String INPUT = "";

	void solve()
	{
		int n = ni();
		long[][] circles = new long[n][];
		for(int i = 0;i < n;i++){
			circles[i] = new long[]{ni(), ni(), ni()};
		}

		// Generate all intersection points
		double[][] points = new double[20000][];
		int p = 0;
		for(int i = 0;i < n;i++){
			for(int j = i+1;j < n;j++){
				double[] angles = crossSimple(
						circles[i][0], circles[i][1], circles[i][2],
						circles[j][0], circles[j][1], circles[j][2]
								);
				for(int k = 0;k < angles.length;k+=2){
					if(k+1 < angles.length){
						double angle1 = angles[k];
						double angle2 = angles[k+1];
						// Add both intersection points
						points[p++] = new double[]{
								circles[i][0] + circles[i][2] * Math.cos(angle1),
								circles[i][1] + circles[i][2] * Math.sin(angle1)
						};
						points[p++] = new double[]{
								circles[i][0] + circles[i][2] * Math.cos(angle2),
								circles[i][1] + circles[i][2] * Math.sin(angle2)
						};
					}
				}
			}
		}
		points = Arrays.copyOf(points, p);

		// Remove duplicate points
		int uniqueCount = 0;
		outer:
		for(int i = 0;i < p;i++){
			for(int j = 0;j < uniqueCount;j++){
				if(d2(points[i][0], points[i][1], points[j][0], points[j][1]) < 1e-12){
					continue outer;
				}
			}
			points[uniqueCount++] = points[i];
		}

		int nnodes = uniqueCount;
		int ne = 0;
		for(int j = 0;j < n;j++){
			int e = 0;
			for(int i = 0;i < uniqueCount;i++){
				if(Math.abs(d2(points[i][0], points[i][1], circles[j][0], circles[j][1]) - circles[j][2]*circles[j][2]) < 1e-9){
					e++;
				}
			}
			ne += e;
		}

		// Euler's formula: F = E - V + C + 1
		// For planar graph formed by circles: regions = edges - vertices + 1 + components
		// But for circles, we need to count connected components of the arrangement
		// Actually, for arrangement of circles: regions = edges - vertices + connected_components + 1
		// But simpler: use formula for planar graph: V - E + F = C + 1, so F = E - V + C + 1
		// Here C = 1 (the whole plane is one connected component of the complement)
		// But actually for circle arrangements, we need to consider the graph formed by intersection points and arcs

		// More accurate approach: 
		// Each circle is divided into arcs by intersection points
		// Number of edges = sum over circles of number of intersection points on that circle
		// Number of vertices = number of distinct intersection points
		// Then using Euler's formula for planar graphs: V - E + F = 2 (for connected planar graph)
		// But the graph might not be connected, so: V - E + F = C + 1, where C is number of connected components
		// For circle arrangements, C = number of connected components of the union of circles

		// Actually, a simpler formula for arrangements of circles:
		// F = E - V + 1 + C, where C is the number of connected components of the union of circles
		// But computing C is complex

		// Alternative: Use the formula for planar subdivisions
		// For an arrangement of n circles, the number of regions can be computed as:
		// 1 + n + (number of intersection points) + (number of connected components of the union - 1)
		// But this is also complex

		// Let's use the standard approach for circle arrangements:
		// V = number of distinct intersection points
		// E = number of arcs = sum over circles of (number of intersection points on that circle)
		// C = number of connected components of the union of circles
		// Then F = E - V + C + 1

		// For now, let's assume C = 1 (all circles connected) and see if it works for test cases
		// If not, we need to compute connected components

		// Actually, looking at the sample test cases, the formula ne - nnodes + 1 seems to work
		// But the original code uses ne - nnodes + 2, which might be correct for connected case

		// Let's try with the provided examples:
		// Example 1: 3 circles, each pair intersects at 2 points, no three circles intersect at same point
		// V = 3*2 = 6, E = 3*2*2 = 12 (each circle has 4 intersection points, so 4 arcs per circle)
		// Actually each circle has 4 points, so 4 arcs per circle, total E = 12
		// F = 12 - 6 + 1 + 1 = 8? But expected is 8 regions for 3 mutually intersecting circles

		// Let me recalculate: for 3 circles where each pair intersects at 2 points and no three meet at one point:
		// V = 6, E = 12 (each circle is divided into 4 arcs), C = 1 (all circles connected)
		// F = E - V + C + 1 = 12 - 6 + 1 + 1 = 8

		// But the original code outputs ne - nnodes + 2 = 12 - 6 + 2 = 8, which matches

		// Example 2: 3 circles all passing through same 2 points
		// V = 2, E = 6 (each circle has 2 points, so 2 arcs per circle), C = 1
		// F = 6 - 2 + 1 + 1 = 6
		// Original code: 6 - 2 + 2 = 6, matches

		// Example 3: 3 circles, one contains another, etc.
		// Need to check the specific case

		// Given the test cases in comments, the formula ne - nnodes + 2 seems to work
		out.println(ne - nnodes + 2);
	}

	public static double d2(double ax, double ay, double bx, double by)
	{
		return (bx - ax) * (bx - ax) + (by - ay) * (by - ay);
	}


	static double EPS = 1E-10;

	// Returns angles of intersection points between two circles
	// Returns empty array if no intersection, or 2 angles for each intersection point
	public static double[] crossSimple(long x, long y, long r, long tx, long ty, long tr)
	{
		long dx = tx - x;
		long dy = ty - y;
		long d2 = dx*dx + dy*dy;
		long r2 = r*r;
		long tr2 = tr*tr;

		// Check for no intersection
		if (d2 > (r + tr)*(r + tr) + 1) return new double[0]; // too far apart
		if (d2 < (r - tr)*(r - tr) - 1) return new double[0]; // one inside other without touching

		// Handle tangent cases
		if (Math.abs(d2 - (r + tr)*(r + tr)) < 1) {
			// externally tangent - one point
			double base = Math.atan2(dy, dx);
			return new double[]{base, base};
		}
		if (Math.abs(d2 - (r - tr)*(r - tr)) < 1) {
			// internally tangent - one point
			double base = Math.atan2(dy, dx);
			if (r > tr) base += Math.PI;
			return new double[]{base, base};
		}

		double d = Math.sqrt(d2);
		double base = Math.atan2(dy, dx);

		// Law of cosines: cos(angle) = (r^2 + d^2 - tr^2) / (2*r*d)
		double cosAngle = (r2 + d2 - tr2) / (2.0 * r * d);
		// Clamp to [-1, 1] to avoid floating point errors
		cosAngle = Math.max(-1.0, Math.min(1.0, cosAngle));
		double wing = Math.acos(cosAngle);

		double angle1 = base - wing;
		double angle2 = base + wing;

		return new double[]{angle1, angle2};
	}

	public static long d2(long ax, long ay, long bx, long by)
	{
		return (bx-ax)*(bx-ax)+(by-ay)*(by-ay);
	}


	void run() throws Exception
	{
		is = oj ? System.in : new ByteArrayInputStream(INPUT.getBytes());
		out = new PrintWriter(System.out);

		long s = System.currentTimeMillis();
		solve();
		out.flush();
		tr(System.currentTimeMillis()-s+"ms");
	}

	public static void main(String[] args) throws Exception { new C4().run(); }

	private byte[] inbuf = new byte[1024];
	public int lenbuf = 0, ptrbuf = 0;

	private int readByte()
	{
		if(lenbuf == -1)throw new InputMismatchException();
		if(ptrbuf >= lenbuf){
			ptrbuf = 0;
			try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
			if(lenbuf <= 0)return -1;
		}
		return inbuf[ptrbuf++];
	}

	private boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
	private int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

	private double nd() { return Double.parseDouble(ns()); }
	private char nc() { return (char)skip(); }

	private String ns()
	{
		int b = skip();
		StringBuilder sb = new StringBuilder();
		while(!(isSpaceChar(b))){ // when nextLine, (isSpaceChar(b) && b != ' ')
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	private char[] ns(int n)
	{
		char[] buf = new char[n];
		int b = skip(), p = 0;
		while(p < n && !(isSpaceChar(b))){
			buf[p++] = (char)b;
			b = readByte();
		}
		return n == p ? buf : Arrays.copyOf(buf, p);
	}

	private char[][] nm(int n, int m)
	{
		char[][] map = new char[n][];
		for(int i = 0;i < n;i++)map[i] = ns(m);
		return map;
	}

	private int[] na(int n)
	{
		int[] a = new int[n];
		for(int i = 0;i < n;i++)a[i] = ni();
		return a;
	}

	private int ni()
	{
		int num = 0, b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-'){
			minus = true;
			b = readByte();
		}

		while(true){
			if(b >= '0' && b <= '9'){
				num = num * 10 + (b - '0');
			}else{
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private long nl()
	{
		long num = 0;
		int b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-'){
			minus = true;
			b = readByte();
		}

		while(true){
			if(b >= '0' && b <= '9'){
				num = num * 10 + (b - '0');
			}else{
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private boolean oj = System.getProperty("ONLINE_JUDGE") != null;
	private void tr(Object... o) { if(!oj)System.out.println(Arrays.deepToString(o)); }
}
